import type { CoachLocale } from '../domain/preferences';
import type { LiveLevel, LiveLine } from '../domain/humor/live';

/**
 * RML-002 Roast Me Live editorial lines (rewritten after the user's QA). Whole lines written per coach,
 * never assembled from swappable insult fragments; each coach has its own references and rhythm:
 * - Luz (SV): fluid run-on delivery, voseo, absurd situations, warm puteadas, quick turn to teaching.
 * - Toño (MX): carrilla, Mexican references, real albures only in double-meaning lines.
 * - Vale (CO, paisa): usted with paisa vocabulary (parce, boleta, dar papaya, tinto), affectionate strong words.
 * - Romi (AR): voseo, dry irony and short punchlines, rioplatense vocabulary.
 * Levels: 0 clean (no consent needed), 1 picante, 2 sin pena, 3 sin misericordia. `double` needs the
 * explicit double-meaning opt-in. Laughter is a visual flag; TTS never reads it. Every error line is
 * tied to a reviewed error the student actually made (`inputs`); jokes never target the person,
 * pronunciation inferred from speech recognition, or sensitive attributes.
 */
type Draft = Omit<LiveLine, 'id' | 'coach'> & { key: string };
type Laugh = LiveLine['laugh'];
type Entry = [LiveLevel, string, Laugh?];
const coach = (locale: CoachLocale, short: string, lines: Draft[]): LiveLine[] =>
  lines.map(({ key, ...line }) => ({ ...line, id: `live-v2:${short}:${line.kind}:${key}`, coach: locale }));
/** Reactions to one reviewed error: level 0 is a clean joke (light); levels 1-3 are roasts. */
const onError = (key: string, when: NonNullable<LiveLine['when']>, entries: Entry[]): Draft[] =>
  entries.map(([level, text, laugh]) => ({ key: `${key}${level}`, kind: level === 0 ? 'light' : 'roast', level, text, when, ...(laugh ? { laugh } : {}) }));

